'use client';

import { useState, useEffect, useCallback, useRef, useSyncExternalStore } from 'react';
import { API_BASE } from '@/lib/api';

export interface VerificationStatusData {
  userId: string;
  isEligible: boolean;
  isGated: boolean;
  gracePeriodActive: boolean;
  daysRemaining: number;
  deadline: string;
  isMobileVerified: boolean;
  isProfileComplete: boolean;
  isRevoked: boolean;
  missingFields: string[];
  errorCode?: string;
  requiredAction?: string;
  message?: string;
  profileUrl?: string;
}

export interface UseVerificationStatusResult {
  loading: boolean;
  isAuthenticated: boolean;
  isMobileVerified: boolean;
  isEligibleForReminder: boolean;
  status: VerificationStatusData | null;
  error: string | null;
  refetch: () => Promise<VerificationStatusData | null>;
}

interface StoredUser {
  id?: string;
  isAdmin?: boolean;
  planType?: string;
  mobileVerified?: boolean;
  mobileVerification?: { verified?: boolean };
}

// Module-level in-memory cache and in-flight request promise
let cachedStatusData: VerificationStatusData | null = null;
let lastCacheTimestamp = 0;
const CACHE_TTL_MS = 60000; // 60-second in-memory freshness guarantee
let inFlightRequest: Promise<VerificationStatusData | null> | null = null;

export const VERIFICATION_STATUS_UPDATED_EVENT = 'trayago_verification_status_updated';

/**
 * Invalidate the module-level verification cache (e.g. after login, logout, or OTP verification).
 */
export function clearVerificationStatusCache(): void {
  cachedStatusData = null;
  lastCacheTimestamp = 0;
  inFlightRequest = null;
}

/**
 * Perform an authoritative network request to fetch the user's verification status,
 * enforcing deduplication and caching rules.
 */
export async function fetchAuthoritativeVerificationStatus(force = false): Promise<VerificationStatusData | null> {
  if (typeof window === 'undefined') return null;

  try {
    const userStr = localStorage.getItem('user');
    const token = localStorage.getItem('accessToken');

    // 1. Guest user check
    if (!userStr || !token) {
      cachedStatusData = null;
      lastCacheTimestamp = 0;
      return null;
    }

    let user: StoredUser | null = null;
    try {
      user = JSON.parse(userStr) as StoredUser;
    } catch {
      cachedStatusData = null;
      lastCacheTimestamp = 0;
      return null;
    }

    // 2. Admins are strictly exempt from mobile verification requirements
    if (user?.isAdmin || user?.planType === 'admin') {
      const adminStatus: VerificationStatusData = {
        userId: user?.id || 'admin',
        isEligible: true,
        isGated: false,
        gracePeriodActive: false,
        daysRemaining: 999,
        deadline: new Date().toISOString(),
        isMobileVerified: true,
        isProfileComplete: true,
        isRevoked: false,
        missingFields: []
      };
      cachedStatusData = adminStatus;
      lastCacheTimestamp = Date.now();
      return adminStatus;
    }

    // 3. Return fresh in-memory cache if not forced and within TTL
    if (!force && cachedStatusData && (Date.now() - lastCacheTimestamp < CACHE_TTL_MS)) {
      return cachedStatusData;
    }

    // 4. Request deduplication: reuse active in-flight promise
    if (!inFlightRequest) {
      inFlightRequest = (async () => {
        try {
          const res = await fetch(`${API_BASE}/auth/verification-status`, {
            headers: {
              Authorization: `Bearer ${token}`,
              'x-user-id': user?.id || ''
            }
          });

          if (res.status === 401) {
            // Session expired
            cachedStatusData = null;
            lastCacheTimestamp = 0;
            return null;
          }

          if (!res.ok) {
            throw new Error(`HTTP_${res.status}`);
          }

          const json = (await res.json()) as { success?: boolean; data?: VerificationStatusData };
          if (json.success && json.data) {
            const data = json.data;
            cachedStatusData = data;
            lastCacheTimestamp = Date.now();

            // Reconcile localStorage user state with authoritative server truth
            if (data.isMobileVerified && !user?.mobileVerified) {
              try {
                const updatedUser = { ...user, mobileVerified: true };
                if (updatedUser.mobileVerification) {
                  updatedUser.mobileVerification.verified = true;
                }
                localStorage.setItem('user', JSON.stringify(updatedUser));
              } catch {
                // Ignore localStorage quota errors
              }
            } else if (!data.isMobileVerified && user?.mobileVerified && data.isRevoked) {
              try {
                const updatedUser = { ...user, mobileVerified: false };
                if (updatedUser.mobileVerification) {
                  updatedUser.mobileVerification.verified = false;
                }
                localStorage.setItem('user', JSON.stringify(updatedUser));
              } catch {
                // Ignore localStorage quota errors
              }
            }

            return data;
          }
          return null;
        } catch {
          // Fail-closed for network / authority errors
          return null;
        } finally {
          inFlightRequest = null;
        }
      })();
    }

    return await inFlightRequest;
  } catch {
    return null;
  }
}

/**
 * Reusable invalidation function:
 * Clears the shared in-memory verification status cache, notifies all active hook listeners,
 * and immediately triggers an authoritative background refresh.
 */
export async function invalidateVerificationStatus(): Promise<VerificationStatusData | null> {
  clearVerificationStatusCache();
  if (typeof window !== 'undefined') {
    window.dispatchEvent(new CustomEvent(VERIFICATION_STATUS_UPDATED_EVENT));
  }
  return fetchAuthoritativeVerificationStatus(true);
}

const emptySubscribe = () => () => {};

/**
 * Authoritative hook to query and manage user mobile verification status.
 * Deduplicates simultaneous requests, enforces 60s memory caching, and handles
 * session expiry and network failures safely without excessive polling.
 */
export function useVerificationStatus(): UseVerificationStatusResult {
  const isClient = useSyncExternalStore(
    emptySubscribe,
    () => true,
    () => false
  );

  const [status, setStatus] = useState<VerificationStatusData | null>(cachedStatusData);
  const [loading, setLoading] = useState<boolean>(!cachedStatusData);
  const [error, setError] = useState<string | null>(null);
  const [isAuthenticated, setIsAuthenticated] = useState<boolean>(false);
  const [isMobileVerified, setIsMobileVerified] = useState<boolean>(Boolean(cachedStatusData?.isMobileVerified));
  const isMountedRef = useRef(true);

  const fetchStatus = useCallback(async (force = false): Promise<VerificationStatusData | null> => {
    if (typeof window === 'undefined') return null;

    try {
      const userStr = localStorage.getItem('user');
      const token = localStorage.getItem('accessToken');

      // 1. Guest user check
      if (!userStr || !token) {
        if (isMountedRef.current) {
          setIsAuthenticated(false);
          setIsMobileVerified(false);
          setStatus(null);
          setLoading(false);
          setError(null);
        }
        return null;
      }

      if (isMountedRef.current) {
        setIsAuthenticated(true);
      }

      const authoritativeData = await fetchAuthoritativeVerificationStatus(force);

      if (!isMountedRef.current) return authoritativeData;

      if (authoritativeData) {
        setStatus(authoritativeData);
        setIsMobileVerified(Boolean(authoritativeData.isMobileVerified));
        setError(null);
      } else {
        // If fetch returned null but user has token, could be offline or expired
        setError('VERIFICATION_AUTHORITY_UNAVAILABLE');
      }
      setLoading(false);
      return authoritativeData;
    } catch (err: unknown) {
      if (isMountedRef.current) {
        setError(err instanceof Error ? err.message : 'UNKNOWN_ERROR');
        setLoading(false);
      }
      return null;
    }
  }, []);

  useEffect(() => {
    isMountedRef.current = true;
    let active = true;

    // Asynchronously trigger fetch outside synchronous effect body
    const init = async () => {
      await Promise.resolve();
      if (active) {
        fetchStatus();
      }
    };
    init();

    // Listen for storage events (e.g. login/logout in another tab)
    const handleStorageChange = (e: StorageEvent) => {
      if (e.key === 'user' || e.key === 'accessToken') {
        clearVerificationStatusCache();
        fetchStatus(true);
      }
    };

    // Listen for local invalidation events (e.g. OTP verification success in current tab)
    const handleStatusUpdated = () => {
      if (isMountedRef.current) {
        fetchStatus(true);
      }
    };

    window.addEventListener('storage', handleStorageChange);
    window.addEventListener(VERIFICATION_STATUS_UPDATED_EVENT, handleStatusUpdated);

    return () => {
      active = false;
      isMountedRef.current = false;
      window.removeEventListener('storage', handleStorageChange);
      window.removeEventListener(VERIFICATION_STATUS_UPDATED_EVENT, handleStatusUpdated);
    };
  }, [fetchStatus]);

  // Existing user eligible for gentle reminder:
  // Authenticated, NOT mobile verified, NOT undergoing mandatory search gating
  const isEligibleForReminder = Boolean(
    isClient &&
    isAuthenticated && 
    status && 
    !status.isMobileVerified && 
    !status.isGated && 
    status.isEligible
  );

  return {
    loading,
    isAuthenticated,
    isMobileVerified,
    isEligibleForReminder,
    status,
    error,
    refetch: () => fetchStatus(true)
  };
}
