'use client';

import { useEffect, useState } from 'react';
import { API_BASE } from './api';
import type {
  MergedTrainCoachFields,
  TrainAvailableClass,
  VerifiedTrainCoachMetadata,
} from './trainCoachMetadata';

export const METADATA_FETCH_TIMEOUT_MS = 9000;

export interface VerifiedTrainMetadata {
  trainNo: string;
  trainName: string | null;
  trainType: string | null;
  trainTypeVerified: boolean;
  daysOfWeek: string[];
  runningDaysVerified: boolean;
  operatingFrequency: string | null;
  stopsCount: number | null;
  totalDistance: number | null;
  totalDistanceLabel: string | null;
  scheduledDurationMinutes: number | null;
  totalDurationLabel: string | null;
  avgSpeedKmh: number | null;
  rakeType: string | null;
  hasPantry: boolean | null;
  availableClasses: TrainAvailableClass[];
  isVerified: true;
}

export interface PnrMetadataCompletenessInput {
  trainNo?: string | null;
  runningDays?: string[] | string | null;
  operatingFrequency?: string | null;
  stopsCount?: number | string | null;
  trainTotalDistance?: number | string | null;
  trainTotalDuration?: string | null;
  trainAvgSpeed?: number | string | null;
}

export interface PnrOverviewMergeInput extends PnrMetadataCompletenessInput {
  trainType?: string | null;
  rakeType?: string | null;
  hasPantry?: boolean | null;
  availableClasses?: TrainAvailableClass[] | null;
}

export interface MergedTrainOverviewFields extends MergedTrainCoachFields {
  trainType?: string;
  operatingFrequency?: string;
  runningDays?: string;
  stopsCount?: number | string;
  trainTotalDistance?: number | string;
  trainTotalDuration?: string;
  trainAvgSpeed?: number | string;
}

const VALID_DAY_TOKENS = new Set(['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun']);

export function normalizeTrainNoForMetadata(trainNo?: string | null): string | null {
  const clean = typeof trainNo === 'string' ? trainNo.trim() : String(trainNo ?? '').trim();
  if (!/^\d{4,5}$/.test(clean)) return null;
  if (/^0+$/.test(clean)) return null;
  return clean.padStart(5, '0');
}

function hasPositiveNumericValue(val: unknown): boolean {
  if (typeof val === 'number') {
    return Number.isFinite(val) && val > 0;
  }
  if (typeof val === 'string') {
    const trimmed = val.trim();
    if (!trimmed) return false;
    const match = trimmed.match(/-?\d+(?:\.\d+)?/);
    if (!match) return false;
    const parsed = Number(match[0]);
    return Number.isFinite(parsed) && parsed > 0;
  }
  return false;
}

function hasNonEmptyString(val: unknown): val is string {
  return typeof val === 'string' && val.trim().length > 0;
}

/**
 * Pure detector for incomplete full-run train metadata on PNR payloads.
 * Returns false for invalid train numbers and for well-populated trains (zero extra calls).
 */
export function isTrainMetadataIncomplete(fields: PnrMetadataCompletenessInput | null | undefined): boolean {
  if (!fields) return false;
  if (!normalizeTrainNoForMetadata(fields.trainNo)) return false;

  const hasOperatingDays =
    hasNonEmptyString(fields.operatingFrequency) ||
    (Array.isArray(fields.runningDays) && fields.runningDays.length > 0) ||
    hasNonEmptyString(fields.runningDays);
  const hasStops = hasPositiveNumericValue(fields.stopsCount);
  const hasDistance = hasPositiveNumericValue(fields.trainTotalDistance);
  const hasDuration = hasNonEmptyString(fields.trainTotalDuration);
  const hasAvgSpeed = hasPositiveNumericValue(fields.trainAvgSpeed);

  return !(hasOperatingDays && hasStops && hasDistance && hasDuration && hasAvgSpeed);
}

/**
 * Pure sequencing guard: defer coach fetch ONLY while incomplete metadata is actively settling.
 * Complete trains (needsMetadataEnrichment === false) never wait; once metadata settles
 * (success, incomplete, error, or timeout), coach fetch is immediately released.
 */
export function shouldDeferCoachFetchForMetadata(
  needsMetadataEnrichment: boolean,
  metadataSettled: boolean
): boolean {
  return Boolean(needsMetadataEnrichment && !metadataSettled);
}

function formatDurationMinutes(minutes: number): string {
  const hours = Math.floor(minutes / 60);
  const mins = minutes % 60;
  return `${hours}:${String(mins).padStart(2, '0')} hr`;
}

/**
 * Fail-closed parser for GET /api/trains/metadata/:trainNo responses.
 * Rejects error/malformed envelopes, unverified running days, and non-positive metrics.
 * Never invents maxSpeedKmh, inauguralYear, zone, or rakeSharing.
 */
export function extractVerifiedTrainMetadata(rawResponseOrData: unknown): VerifiedTrainMetadata | null {
  if (!rawResponseOrData || typeof rawResponseOrData !== 'object') return null;
  const envelope = rawResponseOrData as Record<string, any>;

  if (envelope.success === false) return null;

  const payload =
    envelope.data && typeof envelope.data === 'object' && !Array.isArray(envelope.data)
      ? (envelope.data as Record<string, any>)
      : envelope;

  const rawTrainNo = payload.trainNo ?? payload.train_no;
  const trainNo = normalizeTrainNoForMetadata(typeof rawTrainNo === 'string' || typeof rawTrainNo === 'number' ? String(rawTrainNo) : '');
  if (!trainNo) return null;

  const rawName = payload.trainName ?? payload.train_name;
  const trainName = hasNonEmptyString(rawName) ? rawName.trim() : null;

  const trainTypeVerified = payload.trainTypeVerified === true;
  const rawType = payload.trainType ?? payload.train_type;
  const trainType = trainTypeVerified && hasNonEmptyString(rawType) ? rawType.trim() : null;

  const runningDaysVerified = payload.runningDaysVerified === true;
  const rawDays = Array.isArray(payload.daysOfWeek) ? payload.daysOfWeek : [];
  const daysOfWeek: string[] = runningDaysVerified
    ? rawDays
        .filter((d: unknown): d is string => typeof d === 'string' && VALID_DAY_TOKENS.has(d.trim()))
        .map((d: string) => d.trim())
    : [];

  const operatingFrequency =
    runningDaysVerified && daysOfWeek.length > 0
      ? (daysOfWeek.length === 7 ? 'Daily' : daysOfWeek.join(', '))
      : null;

  const rawStops = payload.stopsCount ?? payload.stops_count;
  const stopsCount =
    typeof rawStops === 'number' && Number.isFinite(rawStops) && rawStops >= 2
      ? Math.round(rawStops)
      : null;

  const rawDistance = payload.totalDistance ?? payload.total_distance;
  const totalDistance =
    typeof rawDistance === 'number' && Number.isFinite(rawDistance) && rawDistance > 0
      ? rawDistance
      : null;
  const totalDistanceLabel = totalDistance !== null ? `${totalDistance} km` : null;

  const rawDuration = payload.scheduledDurationMinutes ?? payload.scheduled_duration_minutes;
  const scheduledDurationMinutes =
    typeof rawDuration === 'number' && Number.isFinite(rawDuration) && rawDuration > 0
      ? Math.round(rawDuration)
      : null;
  const totalDurationLabel =
    scheduledDurationMinutes !== null ? formatDurationMinutes(scheduledDurationMinutes) : null;

  const rawSpeed = payload.avgSpeedKmh ?? payload.avg_speed_kmh;
  const avgSpeedKmh =
    typeof rawSpeed === 'number' && Number.isFinite(rawSpeed) && rawSpeed > 0
      ? Math.round(rawSpeed)
      : null;

  const rawRake = payload.rakeType ?? payload.rake_type;
  const rakeType = hasNonEmptyString(rawRake) ? rawRake.trim() : null;

  const hasPantry =
    typeof payload.hasPantry === 'boolean'
      ? payload.hasPantry
      : (typeof payload.has_pantry === 'boolean' ? payload.has_pantry : null);

  const rawClasses = payload.availableClasses ?? payload.available_classes;
  const availableClasses: TrainAvailableClass[] = Array.isArray(rawClasses)
    ? rawClasses
        .filter(
          (c: any) =>
            c &&
            typeof c.code === 'string' &&
            c.code.trim().length > 0 &&
            typeof c.name === 'string' &&
            c.name.trim().length > 0
        )
        .map((c: any) => ({ code: c.code.trim().toUpperCase(), name: c.name.trim() }))
    : [];

  return {
    trainNo,
    trainName,
    trainType,
    trainTypeVerified,
    daysOfWeek,
    runningDaysVerified: runningDaysVerified && daysOfWeek.length > 0,
    operatingFrequency,
    stopsCount,
    totalDistance,
    totalDistanceLabel,
    scheduledDurationMinutes,
    totalDurationLabel,
    avgSpeedKmh,
    rakeType,
    hasPantry,
    availableClasses,
    isVerified: true,
  };
}

/**
 * Pure non-clobbering merger for TrainStatsCard & RouteStationsTimelineCard.
 * Priority: existing verified PNR payload -> verified /api/trains/metadata -> verified /api/trains/coaches.
 * Never fabricates unsupported optional fields (maxSpeed, inauguralYear, zone, rakeSharing).
 */
export function mergeTrainOverviewMetadata(
  pnrFields: PnrOverviewMergeInput,
  verifiedMeta: VerifiedTrainMetadata | null | undefined,
  verifiedCoachMeta: VerifiedTrainCoachMetadata | MergedTrainCoachFields | null | undefined
): MergedTrainOverviewFields {
  const meta = verifiedMeta && verifiedMeta.isVerified ? verifiedMeta : null;
  const coach = verifiedCoachMeta ?? null;

  const pnrRunningDaysStr = Array.isArray(pnrFields.runningDays)
    ? pnrFields.runningDays.filter((d) => typeof d === 'string' && d.trim()).join(', ')
    : (hasNonEmptyString(pnrFields.runningDays) ? pnrFields.runningDays.trim() : undefined);

  const trainType =
    (hasNonEmptyString(pnrFields.trainType) ? pnrFields.trainType.trim() : undefined) ??
    (meta?.trainType ?? undefined);

  const operatingFrequency =
    (hasNonEmptyString(pnrFields.operatingFrequency) ? pnrFields.operatingFrequency.trim() : undefined) ??
    (meta?.operatingFrequency ?? undefined);

  const runningDays =
    pnrRunningDaysStr ??
    (meta && meta.runningDaysVerified && meta.daysOfWeek.length > 0
      ? meta.daysOfWeek.join(', ')
      : undefined);

  const stopsCount =
    hasPositiveNumericValue(pnrFields.stopsCount)
      ? pnrFields.stopsCount ?? undefined
      : (meta?.stopsCount ?? undefined);

  const trainTotalDistance =
    hasPositiveNumericValue(pnrFields.trainTotalDistance)
      ? pnrFields.trainTotalDistance ?? undefined
      : (meta?.totalDistanceLabel ?? undefined);

  const trainTotalDuration =
    hasNonEmptyString(pnrFields.trainTotalDuration)
      ? pnrFields.trainTotalDuration.trim()
      : (meta?.totalDurationLabel ?? undefined);

  const trainAvgSpeed =
    hasPositiveNumericValue(pnrFields.trainAvgSpeed)
      ? pnrFields.trainAvgSpeed ?? undefined
      : (meta?.avgSpeedKmh ?? undefined);

  const rakeType =
    (hasNonEmptyString(pnrFields.rakeType) ? pnrFields.rakeType.trim() : undefined) ??
    (meta?.rakeType ?? undefined) ??
    (hasNonEmptyString(coach?.rakeType) ? coach!.rakeType!.trim() : undefined);

  const hasPantry =
    typeof pnrFields.hasPantry === 'boolean'
      ? pnrFields.hasPantry
      : typeof meta?.hasPantry === 'boolean'
        ? meta.hasPantry
        : typeof coach?.hasPantry === 'boolean'
          ? coach.hasPantry
          : undefined;

  const availableClasses =
    Array.isArray(pnrFields.availableClasses) && pnrFields.availableClasses.length > 0
      ? pnrFields.availableClasses
      : meta && meta.availableClasses.length > 0
        ? meta.availableClasses
        : Array.isArray(coach?.availableClasses) && coach!.availableClasses!.length > 0
          ? coach!.availableClasses
          : undefined;

  return {
    trainType,
    operatingFrequency,
    runningDays,
    stopsCount,
    trainTotalDistance,
    trainTotalDuration,
    trainAvgSpeed,
    rakeType,
    hasPantry,
    availableClasses,
  };
}

/**
 * Pure non-clobbering overlay that merges verified /api/trains/metadata fields onto
 * a PNR payload record for downstream RouteStationsTimelineCard & TrainStatsCard props.
 * Returns the exact original reference if trainMeta is null or belongs to a different train.
 */
export function applyVerifiedTrainMetadataToPnr<T extends Record<string, any>>(
  rawRecord: T | null,
  verifiedMeta: VerifiedTrainMetadata | null | undefined
): T | null {
  if (!rawRecord || !verifiedMeta || !verifiedMeta.isVerified) return rawRecord;

  const recordTrainNo = normalizeTrainNoForMetadata(
    rawRecord.train_no || rawRecord.train_number || rawRecord.trainNumber || ''
  );
  if (!recordTrainNo || recordTrainNo !== verifiedMeta.trainNo) {
    return rawRecord;
  }

  const merged = mergeTrainOverviewMetadata(
    {
      trainNo: recordTrainNo,
      trainType: rawRecord.train_type ?? null,
      runningDays: rawRecord.running_days ?? null,
      operatingFrequency: rawRecord.operating_frequency ?? null,
      stopsCount: rawRecord.stops_count ?? null,
      trainTotalDistance: rawRecord.train_total_distance ?? null,
      trainTotalDuration: rawRecord.train_total_duration ?? null,
      trainAvgSpeed: rawRecord.train_avg_speed ?? null,
      rakeType: rawRecord.rake_type ?? null,
      hasPantry: typeof rawRecord.has_pantry === 'boolean' ? rawRecord.has_pantry : null,
      availableClasses: Array.isArray(rawRecord.available_classes) ? rawRecord.available_classes : null,
    },
    verifiedMeta,
    null
  );

  return {
    ...rawRecord,
    ...(merged.trainType && !hasNonEmptyString(rawRecord.train_type) ? { train_type: merged.trainType } : {}),
    ...(merged.operatingFrequency && !hasNonEmptyString(rawRecord.operating_frequency)
      ? { operating_frequency: merged.operatingFrequency }
      : {}),
    ...(verifiedMeta.runningDaysVerified &&
    verifiedMeta.daysOfWeek.length > 0 &&
    (!Array.isArray(rawRecord.running_days) || rawRecord.running_days.length === 0)
      ? { running_days: verifiedMeta.daysOfWeek }
      : {}),
    ...(merged.stopsCount !== undefined && !hasPositiveNumericValue(rawRecord.stops_count)
      ? { stops_count: merged.stopsCount }
      : {}),
    ...(merged.trainTotalDistance && !hasPositiveNumericValue(rawRecord.train_total_distance)
      ? { train_total_distance: merged.trainTotalDistance }
      : {}),
    ...(merged.trainTotalDuration && !hasNonEmptyString(rawRecord.train_total_duration)
      ? { train_total_duration: merged.trainTotalDuration }
      : {}),
    ...(merged.trainAvgSpeed !== undefined && !hasPositiveNumericValue(rawRecord.train_avg_speed)
      ? { train_avg_speed: merged.trainAvgSpeed }
      : {}),
    ...(merged.rakeType && !hasNonEmptyString(rawRecord.rake_type) ? { rake_type: merged.rakeType } : {}),
    ...(typeof merged.hasPantry === 'boolean' && typeof rawRecord.has_pantry !== 'boolean'
      ? { has_pantry: merged.hasPantry }
      : {}),
    ...(Array.isArray(merged.availableClasses) &&
    merged.availableClasses.length > 0 &&
    (!Array.isArray(rawRecord.available_classes) || rawRecord.available_classes.length === 0)
      ? { available_classes: merged.availableClasses }
      : {}),
  };
}

// ── Session-level singleflight + once-per-session attempt caches ──
const resolvedMetadataCache = new Map<string, VerifiedTrainMetadata>();
const inFlightMetadataRequests = new Map<string, Promise<VerifiedTrainMetadata | null>>();
const attemptedMetadataTrains = new Set<string>();

export function clearVerifiedTrainMetadataCache(): void {
  resolvedMetadataCache.clear();
  inFlightMetadataRequests.clear();
  attemptedMetadataTrains.clear();
}

export function getInFlightTrainMetadataCount(): number {
  return inFlightMetadataRequests.size;
}

export function hasAttemptedTrainMetadata(trainNo?: string | null): boolean {
  const key = normalizeTrainNoForMetadata(trainNo);
  return key ? attemptedMetadataTrains.has(key) : false;
}

export type TrainMetadataFetcher = (trainNo: string) => Promise<unknown>;

async function defaultMetadataFetcher(trainNo: string): Promise<unknown> {
  const controller = typeof AbortController !== 'undefined' ? new AbortController() : null;
  const timer = controller
    ? setTimeout(() => controller.abort(), METADATA_FETCH_TIMEOUT_MS)
    : null;
  try {
    const res = await fetch(`${API_BASE}/trains/metadata/${encodeURIComponent(trainNo)}`, {
      method: 'GET',
      headers: { Accept: 'application/json' },
      ...(controller ? { signal: controller.signal } : {}),
    });
    if (!res.ok) return null;
    return await res.json();
  } finally {
    if (timer) clearTimeout(timer);
  }
}

/**
 * Singleflight, once-per-session metadata lookup per canonical 5-digit trainNo.
 * - Coalesces concurrent requests (React StrictMode / multi-mount safe).
 * - Caches valid results for the browser session.
 * - Records attempted trains to prevent infinite retry loops when dark-launch flags are OFF
 *   or a train cannot be hydrated.
 * - Never throws; fails closed to null.
 */
export async function fetchVerifiedTrainMetadata(
  trainNo?: string | null,
  fetcher: TrainMetadataFetcher = defaultMetadataFetcher
): Promise<VerifiedTrainMetadata | null> {
  const key = normalizeTrainNoForMetadata(trainNo);
  if (!key) return null;

  const cached = resolvedMetadataCache.get(key);
  if (cached) return cached;

  if (attemptedMetadataTrains.has(key)) {
    return null;
  }

  const existing = inFlightMetadataRequests.get(key);
  if (existing) return existing;

  const promise = (async (): Promise<VerifiedTrainMetadata | null> => {
    try {
      const raw = await fetcher(key);
      const parsed = extractVerifiedTrainMetadata(raw);
      if (parsed) {
        resolvedMetadataCache.set(key, parsed);
      }
      return parsed;
    } catch {
      return null;
    } finally {
      attemptedMetadataTrains.add(key);
      inFlightMetadataRequests.delete(key);
    }
  })();

  inFlightMetadataRequests.set(key, promise);
  return promise;
}

export interface UseVerifiedTrainMetadataResult {
  trainMeta: VerifiedTrainMetadata | null;
  metadataLoading: boolean;
  metadataSettled: boolean;
}

/**
 * Non-blocking React hook for PNR Train Overview enrichment.
 * Only triggers GET /api/trains/metadata/:trainNo when shouldFetch is true (incomplete metadata).
 * Computes metadataSettled synchronously per trainNo to prevent stale-train races and premature coach fetches.
 */
export function useVerifiedTrainMetadata(
  trainNo?: string | null,
  shouldFetch: boolean = true
): UseVerifiedTrainMetadataResult {
  const normalized = normalizeTrainNoForMetadata(trainNo);
  const [trainMeta, setTrainMeta] = useState<VerifiedTrainMetadata | null>(() =>
    normalized ? (resolvedMetadataCache.get(normalized) ?? null) : null
  );
  const [metadataLoading, setMetadataLoading] = useState<boolean>(false);
  const [settledTrainNo, setSettledTrainNo] = useState<string | null>(() =>
    normalized && (resolvedMetadataCache.has(normalized) || attemptedMetadataTrains.has(normalized))
      ? normalized
      : null
  );

  useEffect(() => {
    if (!normalized) {
      setTrainMeta(null);
      setMetadataLoading(false);
      setSettledTrainNo(null);
      return;
    }

    const cached = resolvedMetadataCache.get(normalized);
    if (cached) {
      setTrainMeta(cached);
      setMetadataLoading(false);
      setSettledTrainNo(normalized);
      return;
    }

    if (!shouldFetch || attemptedMetadataTrains.has(normalized)) {
      setTrainMeta(null);
      setMetadataLoading(false);
      setSettledTrainNo(normalized);
      return;
    }

    let cancelled = false;
    setTrainMeta(null);
    setMetadataLoading(true);

    fetchVerifiedTrainMetadata(normalized).then((result) => {
      if (cancelled) return;
      setTrainMeta(result);
      setMetadataLoading(false);
      setSettledTrainNo(normalized);
    });

    return () => {
      cancelled = true;
    };
  }, [normalized, shouldFetch]);

  const metadataSettled =
    !shouldFetch ||
    !normalized ||
    settledTrainNo === normalized ||
    resolvedMetadataCache.has(normalized) ||
    attemptedMetadataTrains.has(normalized);

  const activeTrainMeta = trainMeta && trainMeta.trainNo === normalized ? trainMeta : null;

  return {
    trainMeta: activeTrainMeta,
    metadataLoading,
    metadataSettled,
  };
}
